<template><form class="form" @submit.prevent="submit"><UiInput v-model="form.judul" label="Judul" required /><div class="field"><label>Kategori</label><select v-model="form.kategori_id"><option value="">Tanpa kategori</option><option v-for="item in kategori" :key="item.id" :value="item.id">{{ item.nama }}</option></select></div><UiInput v-model="form.ringkasan" label="Ringkasan" required /><div class="field"><label>Isi berita</label><textarea v-model="form.isi" required /></div><div class="field"><label>Status</label><select v-model="form.status"><option value="draft">Draft</option><option value="published">Published</option></select></div><div class="field"><label>Thumbnail</label><input type="file" accept="image/*" @change="selectFile" /><img v-if="previewUrl" class="form-preview" :src="previewUrl" alt="Preview thumbnail"></div><UiButton type="submit" icon="heroicons:check">{{ submitLabel }}</UiButton></form></template>
<script setup lang="ts">
const props=defineProps({ initial: { type:Object, default:()=>({}) }, kategori: { type:Array, default:()=>[] }, submitLabel: { default:'Simpan berita' } }); const emit=defineEmits(['submit']); const config=useRuntimeConfig(); const form=reactive({ judul:props.initial.judul||'', kategori_id:props.initial.kategori_id||'', ringkasan:props.initial.ringkasan||'', isi:props.initial.isi||'', status:props.initial.status||'draft', thumbnail:null as File|null }); const previewUrl=ref(props.initial.thumbnail ? `${config.public.uploadsBase}${props.initial.thumbnail}` : ''); function selectFile(event:Event){ const file=(event.target as HTMLInputElement).files?.[0]; if(file){ form.thumbnail=file; previewUrl.value=URL.createObjectURL(file) } } function submit(){ const data=new FormData(); Object.entries(form).forEach(([key,value])=>{ if(value !== null && value !== '') data.append(key,value as string|Blob) }); emit('submit',data) }
</script>
